            _q(2, 3, 'basic', 'Nhìn đồng hồ chỉ thời gian buổi tối ở hình dưới. Nếu em bắt đầu ngồi vào bàn tự học lúc 19 giờ 30 và kết thúc lúc 20 giờ 30, em đã dành bao nhiêu thời gian tự học buổi tối?', '1 giờ (60 phút), vừa đủ hoàn thành bài tập mà vẫn còn thời gian đọc truyện trước khi ngủ lúc 21 giờ', ['5 tiếng đồng hồ liên tục tới nửa đêm', 'Chỉ 5 phút cho xong', '10 tiếng đồng hồ'],
               'Với lớp 2, tập trung tự học 45–60 phút buổi tối kèm 15–20 phút đọc sách thư giãn là vô cùng hợp lí.', 'Quỹ giờ tự học buổi tối',
               fig=fig_clock(7, 30, '19 giờ 30 tối: Bắt đầu giờ tự học')),
